import { MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const { Group, PlaneGeometry, Mesh, TextureLoader } = ctx.THREE;

  const group = new Group();

  // Geometry matching atlas region aspect ratio (512/320 = 1.6)
  const width = 1.6;
  const height = 1.0;
  const geometry = new PlaneGeometry(width, height);

  // Temporary material while texture loads
  const material = new MeshBasicNodeMaterial({
    color: 0x0b0b10, // surface color as fallback
    transparent: false
  });

  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // Position / rotation / scale from config (already applied by adapter, but apply again for safety)
  if (config.scenePosition) {
    group.position.copy(config.scenePosition);
    group.rotation.set(config.scenePosition.x, config.scenePosition.y, config.scenePosition.z);
    if (config.sceneScale) group.scale.copy(config.sceneScale);
  } else {
    group.position.set(-3.2, -0.3, 0);
  }

  // Load texture
  const imageUrl = config.imageUrl || '/prism-mock/home/nodes/orb-decor.png';
  let texture = null;
  ctx.textureLoader.loadTexture(imageUrl).then(tex => {
    texture = tex;
    // If atlas source rect dimensions differ from full texture, set offset/repeat
    // Assume the loaded image is exactly 512x320, so no adjustment needed.
    material.map = tex;
    material.needsUpdate = true;
  }).catch(() => {
    // fallback: keep surface color
  });

  // User data for cleanup and events
  group.userData.handlers = {};
  group.userData.cleanup = () => {
    if (texture) texture.dispose();
    material.dispose();
    geometry.dispose();
  };

  return group;
}
